def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    opp = [h[1] for h in history]
    opp_def = opp.count('D')
    if opp[-1] == 'D':
        if n >= 6 and opp_def == 1:
            return 'C'
        return 'D'
    return 'C'
